-- 238 DRG 国家版 CHS-DRG 2.0 + 3.0 整体数据铺底（biz_drg_* 前缀，郴州基线 + 3.0 接入）
-- 来源：已部署库 hn_biz_his 当前 5 张 biz_drg_* 配置表全量导出（2.0 + 3.0 两个版本）
-- 说明：本脚本所涉均为配置表，重灌一律物理删（DELETE by version），不走软删。
--       全列导出（含 create_time/update_time/create_by_id/update_by_id），无需预置 ALTER。
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
START TRANSACTION;

DELETE FROM biz_drg_mdc WHERE version IN ('chs-drg-2.0','3.0');

DELETE FROM biz_drg_adrg WHERE version IN ('chs-drg-2.0','3.0');

DELETE FROM biz_drg_set WHERE version IN ('chs-drg-2.0','3.0');

DELETE FROM biz_drg_ccmcc WHERE version IN ('chs-drg-2.0','3.0');

DELETE FROM biz_drg_group WHERE version IN ('chs-drg-2.0','3.0');

COMMIT;
